begin;
create function pg_temp.check_report(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.expect_report(statement text,code text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: %',label;end$$;
insert into auth.users(id) values ('60110000-0000-4000-8000-000000000001'),('60110000-0000-4000-8000-000000000002');
insert into access_private.mutation_keys values('synthetic-report-test',decode(repeat('ad',32),'hex'));
insert into public.properties values('hu60-report-property','60110000-0000-4000-8000-000000000001','{}','2026-10-13T00:00:00Z');
create function pg_temp.report_ticket(m jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare msg text;begin msg=(jsonb_build_object('keyId','synthetic-report-test','expires',floor(extract(epoch from clock_timestamp()))+120,'actor',auth.uid(),'inputHash','synthetic-report','module','expense:report','audit','{}'::jsonb,'kind','expense-report','propertyId','hu60-report-property','propertyVersion','2026-10-13T00:00:00Z')||m)::text;return public.commit_validated_owner_change(msg,encode(extensions.hmac(convert_to(msg,'UTF8'),decode(repeat('ad',32),'hex'),'sha256'),'hex'));end$$;
select set_config('request.jwt.claim.sub','60110000-0000-4000-8000-000000000001',true);
set local role authenticated;
select pg_temp.check_report(pg_temp.report_ticket('{"requestId":"create-report","report":{"id":"hu60-report-a","totals":{"actual":10}}}')->>'id'='hu60-report-a','report stored with verified owner');
select pg_temp.check_report((pg_temp.report_ticket('{"requestId":"create-report","report":{"id":"hu60-report-a","totals":{"actual":10}}}')->>'replayed')::boolean and (select count(*)=1 from public.expense_reports),'report retry does not duplicate');
select pg_temp.expect_report($q$select pg_temp.report_ticket('{"requestId":"stale","propertyVersion":"2026-10-12T00:00:00Z","report":{"id":"hu60-report-b"}}')$q$,'40001','stale property prevents report creation');
select pg_temp.expect_report($q$select pg_temp.report_ticket('{"requestId":"book-stale","bookVersion":"2026-10-12T00:00:00Z","report":{"id":"hu60-report-b"}}')$q$,'40001','stale book prevents report creation');
select pg_temp.expect_report($q$select pg_temp.report_ticket('{"requestId":"baseline-stale","kind":"report-download","baselineId":"wrong","reportId":"download"}')$q$,'40001','changed approved baseline prevents report download audit');
select pg_temp.check_report(pg_temp.report_ticket('{"requestId":"download","kind":"report-download","reportId":"download-id"}')->>'id'='download-id' and (select count(*)=1 from public.expense_reports),'download is audited without creating a budget cut');
reset role;
create function pg_temp.fail_report_audit() returns trigger language plpgsql as $$begin if new.id like '%:report-fail' then raise exception using errcode='P0001',message='synthetic report audit failure';end if;return new;end$$;
create trigger hu60_report_fail before insert on public.audit_events for each row execute function pg_temp.fail_report_audit();
set local role authenticated;
select pg_temp.expect_report($q$select pg_temp.report_ticket('{"requestId":"report-fail","report":{"id":"hu60-report-fail"}}')$q$,'P0001','report audit failure propagates');
select pg_temp.check_report(not exists(select 1 from public.expense_reports where id='hu60-report-fail'),'report rolled back with failed audit');
select pg_temp.check_report(not has_function_privilege('anon','public.owner_audit_page(text,timestamptz,text)','execute') and not has_table_privilege('authenticated','public.expense_reports','update'),'no anonymous audit listing or direct report overwrite');
select set_config('request.jwt.claim.sub','60110000-0000-4000-8000-000000000002',true);
select pg_temp.check_report(jsonb_array_length(public.owner_audit_page('hu60-report-property'))=0 and not exists(select 1 from public.expense_reports),'reports and audit isolated from other owner');
select pg_temp.expect_report($q$select pg_temp.report_ticket('{"requestId":"foreign","report":{"id":"foreign"}}')$q$,'42501','foreign property cannot receive report');
reset role;
insert into public.audit_events(id,user_id,property_id,module,payload,created_at) select 'hu60-page-'||lpad(n::text,3,'0'),'60110000-0000-4000-8000-000000000001','hu60-report-property','test','{}','2026-01-01T00:00:00Z' from generate_series(1,102) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','60110000-0000-4000-8000-000000000001',true);
select pg_temp.check_report(jsonb_array_length(public.owner_audit_page('hu60-report-property','2026-01-02T00:00:00Z'))=101 and jsonb_array_length(public.owner_audit_page('hu60-report-property','2026-01-01T00:00:00Z','hu60-page-003'))=2,'timestamp and id cursor preserves ties across pages');
reset role;
rollback;
